function solve(customer, plan, daysSincePurchase) {
  // Standard refund window is 30 days after purchase
  // Acme annual-plan has a 7-day window
  // Acme monthly plans have the standard 30-day window
  // Refund requests on the last day of the window are eligible

  let maxDays;

  if (customer === 'Acme' && plan === 'annual') {
    maxDays = 7;
  } else if (customer === 'Acme' && plan === 'monthly') {
    maxDays = 30;
  } else {
    // Other customers get the standard 30-day window
    maxDays = 30;
  }

  // Check if daysSincePurchase is within the window (inclusive)
  return daysSincePurchase <= maxDays;
}
